module top_module(
    input wire clkm,
	 input wire reset,
    input wire [6:0] division,
    output reg Fr
    );reg signed [6:0] frec;

	always@(posedge clkm, posedge reset) 
	if (reset)begin
		frec <=7'b0000000;
		Fr <=0; 
		end
	else 
		if (frec==division)begin
		frec<=7'b0000000;
		Fr <= ~ Fr;
		end
		else
		frec<=frec+ 7 'd1;

endmodule

