    input Reset,
    input CLK100MHZ,
    output reg [31:0] outClock
    );always @(posedge CLK100MHZ or negedge Reset)
		if(!Reset)
			outClock <= 32'h00000000;
		else
			outClock <= outClock + 1'b1;

endmodule

