module top_module (
        input clk,
        input areset,
        input unlock_signal,
        input lock_signal,
        output reg door_locked);parameter Locked=1'b0, Unlocked=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Locked;
		else begin
			case (state)
				Locked: state <= unlock_signal ? Unlocked : Locked;
				Unlocked: state <= lock_signal ? Locked : Unlocked;
			endcase
		end
	end

	assign door_locked = (state == Locked);

endmodule

