        if (SET) begin
            Q <= 1;
            Qbar <= 0;
        end else if (CLR) begin
            Q <= 0;
            Qbar <= 1;
        end else begin
            Q <= D;
            Qbar <= ~D;
        end
    end
end

endmodule

