description:
Design a synchronization circuit for an asynchronous reset signal. When the active-low reset input (rst_n) is asserted, the module holds the output reset (rst) low for a specified number of clock cycles (delay_cycles). After the reset condition is released, the reset output is held low until the defined delay is completed, allowing for stabilized operation of downstream components. This ensures that the system is appropriately reset in a synchronous manner, preventing any timing issues due to the immediate deassertion of the reset signal.
module top_module(
  input clk,
  input rst_n,
  output rst
);

code:
module top_module(
  input clk,
  input rst_n,
  output rst
);parameter delay_cycles = 10; // number of clock cycles to wait after reset

reg rst_synced;
reg [7:0] rst_counter;

always @(posedge clk) begin
  if (!rst_n) begin
    rst_synced <= 1'b0;
    rst_counter <= 8'd0;
  end
  else begin
    if (rst_n && !rst_synced) begin
      rst_counter <= rst_counter + 1;
      if (rst_counter == delay_cycles) begin
        rst_synced <= 1'b1;
      end
    end
    else begin
      rst_synced <= 1'b0;
      rst_counter <= 8'd0;
    end
  end
end

assign rst = rst_synced;

endmodule

