module traffic_light_controller(
        input clk,
        input reset,
        output reg [2:0] light);

    reg [5:0] counter;
    reg [1:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            state <= 2'b00;
            light <= 3'b100; // Red light
        end else begin
            counter <= counter + 1;
            case (state)
                2'b00: begin // Red state
                    if (counter == 49) begin
                        counter <= 0;
                        state <= 2'b01;
                        light <= 3'b001; // Green light
                    end
                end
                2'b01: begin // Green state
                    if (counter == 29) begin
                        counter <= 0;
                        state <= 2'b10;
                        light <= 3'b010; // Yellow light
                    end
                end
                2'b10: begin // Yellow state
                    if (counter == 9) begin
                        counter <= 0;
                        state <= 2'b00;
                        light <= 3'b100; // Red light
                    end
                end
                default: begin
                    state <= 2'b00;
                    light <= 3'b100; // Default to Red light
                end
            endcase
        end
    end
endmodule

