module top_module(
    input A,
    input B,
    input C,
    input five_cents,
    input ten_cents,
    input twentyfive_cents,
    output reg X_dispense,    // changed to reg
    output reg Y_dispense,    // changed to reg
    output reg Z_dispense,    // changed to reg
    output reg five_cents_return,   // changed to reg
    output reg ten_cents_return,     // changed to reg
    output reg twentyfive_cents_return // changed to reg
);reg [7:0] total_inserted;
    reg [7:0] price_X = 25;
    reg [7:0] price_Y = 50;
    reg [7:0] price_Z = 75;
    reg [7:0] change;

    always @(*) begin
        // Initialize outputs
        X_dispense = 0;
        Y_dispense = 0;
        Z_dispense = 0;
        five_cents_return = 0;
        ten_cents_return = 0;
        twentyfive_cents_return = 0;

        // Dispensing Logic
        if (A && total_inserted >= price_X) begin
            X_dispense = 1;
            change = total_inserted - price_X;
        end else if (B && total_inserted >= price_Y) begin
            Y_dispense = 1;
            change = total_inserted - price_Y;
        end else if (C && total_inserted >= price_Z) begin
            Z_dispense = 1;
            change = total_inserted - price_Z;
        end else begin
            change = total_inserted;
        end

        // Change Return Logic
        if (change >= 25) begin
            twentyfive_cents_return = 1;
            change = change - 25;
        end
        if (change >= 10) begin
            ten_cents_return = 1;
            change = change - 10;
        end
        if (change >= 5) begin
            five_cents_return = 1;
            change = change - 5;
        end
    end

    always @(posedge five_cents or posedge ten_cents or posedge twentyfive_cents) begin
        if (five_cents) begin
            total_inserted = total_inserted + 5;
        end
        if (ten_cents) begin
            total_inserted = total_inserted + 10;
        end
        if (twentyfive_cents) begin
            total_inserted = total_inserted + 25;
        end
    end

endmodule

module top_module(input line_clk, output vsync, output blank, output [11:0] row);parameter v_res = 768;
   parameter v_front_porch = 1;
   parameter v_sync = 3;
   parameter v_back_porch = 36;
   parameter v_total = v_res + v_front_porch + v_sync + v_back_porch;

   reg [12:0] vcount = 0;
   reg [11:0] row_count = 0;

   always @ (posedge line_clk) begin
     $monitor("%0t %m, vcount=%d, vsync=%b, blank=%b, row_count=%d", $time, vcount, vsync, blank, row_count);
     if(vcount < v_total) begin 
       vcount <= vcount + 1'b1;
     end else begin
       vcount <= 0;
     end

     row_count <= blank ? 12'b0 : row_count + 1'b1;
   end

   assign vsync = !(vcount > (v_res + v_front_porch) && vcount <= (v_res + v_front_porch + v_sync));
   assign blank = vcount > v_res;
   assign row = row_count;endmodule

