module binary_counter (
    input clk,
    input clear,
    output reg [11:0] count
);

    always @(posedge clk or posedge clear) begin
        if (clear) begin
            count <= 12'b000000000000;
        end else begin
            count <= count + 12'b000000000001;
        end
    end
endmodule

