Implement the Verilog module based on the following description.
Build a 1-bit JK flip-flop with synchronous set and reset.
// (1) set: Sets flip-flop to one. Synchronous active high.
// (2) reset: Resets flip-flop to zero. Synchronous active high.
// (3) j: J input of the JK flip-flop.
// (4) k: K input of the JK flip-flop.
// (5) q: The contents of the flip-flop.
module top_module(
	input clk,
	input set,
	input reset,
	input j,
	input k,
	output reg q);

code:
module top_module(
	input clk,
	input set,
	input reset,
	input j,
	input k,
	output reg q);always @(posedge clk) begin
	if (reset)
		q <= 1'b0;
	else if (set)
		q <= 1'b1;
	else if (j && ~k)
		q <= 1'b1;
	else if (~j && k)
		q <= 1'b0;
	else if (j && k)
		q <= ~q;
end
endmodule

