    input rst,
    input [3:0] bin_in,
    output reg [3:0] bcd_out
);always @ (posedge clk or posedge rst) begin
        if (rst) begin
            bcd_out <= 4'b0;
        end else begin
            case (bin_in)
                4'b0000: bcd_out <= 4'b0000;
                4'b0001: bcd_out <= 4'b0001;
                4'b0010: bcd_out <= 4'b0010;
                4'b0011: bcd_out <= 4'b0011;
                4'b0100: bcd_out <= 4'b0100;
