module top_module(
    input wire in1,
    input wire in2,
    input wire in3,
    input wire in4,
    input wire clk
);reg [4:0] counter = 0;
    reg [4:0] inputs = 0;

    always @(posedge clk) begin
        if (in1 == 1 && in2 == 1 && in3 == 1 && in4 == 1) begin
            if (counter < 5) begin
                counter <= counter + 1;
            end else begin
                inputs <= 0;
                counter <= 0;
            end
        end else begin
            inputs <= 0;
            counter <= 0;
        end
    end

    assign {in1, in2, in3, in4} = inputs;

endmodule

module johnson_counter(
    input wire clk,
    input wire rst_n,
    output reg [2:0] count
    );

always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        count <= 3'b000;
    else
        count <= {count[1:0], ~count[2]};
end

endmodule

module top_module(
  input clk,
  input reset,
  input enable,
  output reg [2:0] count
);always @(posedge clk) begin
    if (reset) begin
      count <= 3'b0;
    end else if (enable) begin
      case (count)
        3'b000: count <= 3'b001;
        3'b001: count <= 3'b010;
        3'b010: count <= 3'b011;
        3'b011: count <= 3'b100;
        3'b100: count <= 3'b101;
        3'b101: count <= 3'b110;
        3'b110: count <= 3'b000;
      endcase
    end
  end

endmodule

