description:
Design a binary-to-BCD converter that translates a 10-bit binary input into a 12-bit Binary-Coded Decimal (BCD) output. The module uses a shift-and-add 3 algorithm to convert the binary value into three separate BCD digits (units, tens, hundreds). The BCD representation is assembled from three 4-bit registers, where each BCD digit is adjusted if its value exceeds 5, ensuring proper encoding into BCD format, and ultimately outputs a 12-bit result where each BCD digit is represented in 4-bit segments.
module top_module(

	input [9:0] bin,


	output [11:0] BCD
);

code:
module top_module(

	input [9:0] bin,


	output [11:0] BCD
);reg [3:0] units [2:0];

integer i, j;
always @(bin)
begin

	for (j = 2; j >= 0; j = j - 1)
		units[j] = 0;


	for (i = 9; i >= 0; i = i - 1) begin


		for (j = 2; j >= 0; j = j - 1) begin
			if (units[j] >= 5)
				units[j] = units[j] + 3;
		end



		for (j = 2; j >= 0; j = j - 1) begin
			units[j] = units[j] << 1;

			if (j == 0)


				units[j][0] = bin[i];
			else
				units[j][0] = units[j-1][3];
		end
	end
end


genvar z;
generate
	for (z = 0; z < 3; z = z + 1) begin : assign_BCD
		assign BCD[4*(z+1)-1-:4] = units[z];
	end
endgenerate

endmodule

