	output reg Q,
	input C, R, D, S
);always @(negedge C) begin
		if (R == 1'b0) begin
			Q <= 1'b0;
		end else if (S == 1'b1) begin
			Q <= 1'b1;
		end else begin
			Q <= D;
		end
	end

`ifdef ICE40_HX
