module top_module(clock, reset, enable, sdi,
                          count, spiclockp, spiclockn, picready, starting,
                          sclk, done, data);input clock, spiclockp, spiclockn, reset, enable, sdi, picready;
    input [4:0] count;
    output sclk, starting, done;
    output [127:0] data;

    wire clock, enable;
    wire [127:0] data;
    wire [4:0] count;
    reg sclk, starting;
    wire sdi, picready;

    reg [127:0] latch;
    reg [7:0] left;

    reg sample, ready, receive_next;
    wire receiving, done;

    always @(negedge clock or negedge reset)
    begin
        if (~reset)
        begin
            ready <= 1;
            left <= 0;
            starting <= 0;
        end
        else
        begin
            if (spiclockn)
            begin
                sclk <= 0;
                starting <= 0;
                if (~enable)
                begin
                    ready <= 1;
                    left <= 0;
                end
                else if (ready)
                begin
                    left <= {count, 3'b0};
                    ready <= 0;
                end
                else if (left > 0 && receive_next)
                begin
                    latch <= {latch[126:0], sample};
                    left <= left - 8'd1;
                end
            end
            else if (spiclockp && receiving)
            begin
                if (left[2:0] != 3'b000 | picready)
                begin
                    sample <= sdi;
                    sclk <= 1;
                    receive_next <= 1;
                    starting <= left[2:0] == 3'b000;
                end
                else
                begin
                    receive_next <= 0;
                end
            end
        end
    end

    assign done = ~ready & (left == 0);
    assign receiving = ~ready & ~done;
    assign data = latch;

endmodule

