module sequence_detector (
    input clk,
    input in,
    input reset,
    output found);parameter S0=0, S1=1, S10=2, S100=3, S1001=4;
    reg [2:0] state;
    reg [2:0] next;

    always_comb begin
        case (state)
            S0: next = in ? S1 : S0;
            S1: next = in ? S1 : S10;
            S10: next = in ? S100 : S0;
            S100: next = in ? S1 : S1001;
            S1001: next = in ? S1 : S0;
        endcase
    end

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next;
    end

    assign found = (state == S1001);

endmodule

