module top_module (
        input clk,
        input areset,
        input start_wash,
        input stop_wash,
        output reg machine_on);parameter Idle=1'b0, Washing=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Idle;
		else begin
			case (state)
				Idle: state <= start_wash ? Washing : Idle;
				Washing: state <= stop_wash ? Idle : Washing;
			endcase
		end
	end

	assign machine_on = (state == Washing);

endmodule

